<script setup lang="ts">
import {computed,ref,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import PageHeading from '../components/common/PageHeading.vue'
import {useDemoStore} from '../stores/demo'
import {datasetProjects} from '../api/datasetUploads'
const store=useDemoStore(),router=useRouter(),search=ref(''),format=ref(''),project=ref(''),error=ref(''),loading=ref(false)
const formats=computed(()=>[...new Set(store.datasets.map(d=>d.format))])
const rows=computed(()=>store.datasets.filter(d=>(!project.value||(d.project||'未分类')===project.value)&&(!format.value||d.format===format.value)&&`${d.name} ${d.path}`.toLowerCase().includes(search.value.toLowerCase())))
async function refresh(){loading.value=true;try{await store.syncUploadedDatasets();error.value=''}catch(e){error.value=e instanceof Error?e.message:'数据集服务连接失败。'}finally{loading.value=false}}
const open=(id:string)=>router.push('/datasets/'+encodeURIComponent(id))
onMounted(refresh)
</script>
<template><PageHeading title="数据集" description="按机器人项目组织数据，浏览 Episodes 与多相机视频。" badge="数据管理" notice="真实数据支持视频与元数据预览；Mock 条目不包含真实文件。"><button class="button primary" @click="router.push('/datasets/new')">新建数据集</button></PageHeading><div v-if="error" class="form-error" role="alert">{{error}}</div><div class="project-tabs"><button :class="{active:!project}" @click="project=''">全部项目 <b>{{store.datasets.length}}</b></button><button v-for="p in datasetProjects" :key="p" :class="{active:project===p}" @click="project=p">{{p}} <b>{{store.datasets.filter(d=>(d.project||'未分类')===p).length}}</b></button></div><div class="page-toolbar"><input v-model="search" placeholder="搜索数据集或路径…" aria-label="搜索数据集"/><select v-model="format" aria-label="筛选格式"><option value="">全部格式</option><option v-for="f in formats" :key="f">{{f}}</option></select><button class="button" :disabled="loading" @click="refresh">{{loading?'刷新中…':'刷新列表'}}</button><span class="muted">{{rows.length}} 个数据集</span></div><section class="panel page-table"><table><thead><tr><th>数据集 / 服务端路径</th><th>项目</th><th>格式</th><th>Episodes</th><th>大小</th><th>来源</th><th>操作</th></tr></thead><tbody><tr v-for="d in rows" :key="d.id"><td><button class="dataset-name" @click="open(d.id)">{{d.name}}</button><div class="path-text">{{d.path}}</div></td><td><span class="project-chip">{{d.project||'未分类'}}</span></td><td>{{d.format}}</td><td>{{d.episodes?d.episodes.toLocaleString():'进入后解析'}}</td><td>{{d.size}}</td><td>{{d.source==='upload'?'真实数据':'Mock'}}</td><td><button class="text-link" @click="open(d.id)">可视化 →</button></td></tr></tbody></table><div v-if="!rows.length" class="empty-state">该项目下没有匹配的数据集。</div></section><div class="info-note">支持 LeRobot v2.1 / v3.0。进入数据集可修改项目分类、查看视频与数据字段；压缩包需解压后重新导入。</div></template>
<style scoped>.project-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:4px 0 24px}.project-tabs button{background:var(--surface);color:var(--muted);border:1px solid var(--border);border-radius:8px;padding:11px 16px;cursor:pointer}.project-tabs button.active{background:var(--blue);color:white;border-color:var(--blue)}.project-tabs b{margin-left:8px;opacity:.7;font-size:11px}.dataset-name{background:none;border:0;color:var(--text);font:inherit;font-weight:600;cursor:pointer;text-align:left}.dataset-name:hover{color:var(--blue)}.project-chip{border:1px solid var(--border);padding:4px 8px;border-radius:5px;font-size:11px;white-space:nowrap}</style>
